#include "FormationAcceptance.hpp"
#include "CelestialBodyPanel.hpp"
#include "ResourceEditor.hpp"
#include "ReportViewer.hpp"
#include <QComboBox>
#include <QDialog>
#include <QDialogButtonBox>
#include <QLineEdit>
#include <QPushButton>
#include <QTabWidget>
#include <QTimer>
using namespace formaccept;
int main(int argc,char **argv) {
 QApplication::setAttribute(Qt::AA_DontUseNativeDialogs);QApplication app(argc,argv);app.setOrganizationName("GMATTests");app.setApplicationName("NasaEarthFk5");
 try {
  require(argc==3,"Supply startup and independent Earth FK5 cases");const auto matrix=QJsonDocument::fromJson(read(QFileInfo(argv[2]).absoluteFilePath())).object();const auto rows=matrix["rows"].toArray();require(rows.size()==105,"Earth FK5 full basis matrix missing");Rig rig(QFileInfo(argv[1]).absoluteFilePath());
  QString source="% Independent Earth FK5 orientation Ω\nEarth.NutationUpdateInterval = 60;\nCreate CoordinateSystem Inertial Fixed;\nInertial.Origin = Earth;\nInertial.Axes = MJ2000Eq;\nFixed.Origin = Earth;\nFixed.Axes = MJ2000Eq;\nCreate Spacecraft Sat;\nSat.CoordinateSystem = Inertial;\nSat.DisplayStateType = Cartesian;\nCreate Variable Keep;\nKeep = 41;\nCreate ReportFile States;\nStates.Filename = '"+rig.report+"';\nStates.WriteHeaders = false;\nStates.FixedWidth = false;\nStates.Delimiter = ',';\nStates.Precision = 17;\n";
  QString mission="BeginMissionSequence;\n";const QStringList fields{"X","Y","Z","VX","VY","VZ"};
  for(const auto value:rows){const auto row=value.toObject();mission+="Sat.TAIModJulian = "+number(row["tai_mjd"].toDouble())+";\n";for(int i=0;i<6;++i)mission+="Sat.Inertial."+fields[i]+" = "+number(row["input_state"].toArray()[i].toDouble())+";\n";mission+="Report States Sat.TAIModJulian Sat.TTModJulian";for(const auto &frame:QStringList{"Inertial","Fixed"})for(const auto &field:fields)mission+=" Sat."+frame+"."+field;mission+=";\n";}mission+="Keep = Keep + 1; % preserve following command\n";source+=mission;rig.source->setPlainText(source);const bool built=rig.window.buildScript();events();rig.save("build-messages.txt",rig.messages->toPlainText().toUtf8());require(built,"Earth FK5 initial fixture failed Build");rig.save("initial.script",source.toUtf8());
  auto open=[&](const QString &name){auto found=rig.resources->findItems(name,Qt::MatchExactly|Qt::MatchRecursive);require(found.size()==1,"Earth FK5 resource absent");rig.resources->itemDoubleClicked(found.first(),0);events();auto *owner=rig.area->activeSubWindow();require(owner,"Earth FK5 editor absent");owner->showNormal();owner->resize(rig.area->viewport()->size());acceptanceView(*owner);return owner;};
  auto *owner=open("Fixed");auto *panel=dynamic_cast<ResourceEditor *>(owner->widget());require(panel,"Earth FK5 coordinate editor absent");const auto base=rig.source->toPlainText();std::exception_ptr error;
  QTimer::singleShot(0,panel,[&]{auto *d=panel->findChild<QDialog *>("coordinateAxesDialog");try{require(d,"Actual Earth BodyFixed chooser missing");auto *type=d->findChild<QComboBox *>("coordinateAxisType");require(type&&type->findText("BodyFixed")>=0,"Earth BodyFixed choice missing");type->setCurrentText("BodyFixed");events();acceptanceView(*d);d->findChild<QDialogButtonBox *>("resourceButtons")->button(QDialogButtonBox::Apply)->click();require(d->result()==QDialog::Accepted,"Earth BodyFixed nested Apply failed");}catch(...){error=std::current_exception();if(d)d->reject();}});panel->findChild<QPushButton *>("editCoordinateAxes")->click();if(error)std::rethrow_exception(error);require(panel->hasChanges()&&rig.source->toPlainText()==base,"Nested Earth frame selection leaked");panel->requestApply();events();require(Moderator::Instance()->GetConfiguredObject("Fixed")->GetStringParameter("Axes")=="BodyFixed","Earth BodyFixed native choice differs");rig.closePanels();
  auto earth=[&]{return Moderator::Instance()->GetConfiguredObject("Earth");};
  auto viewEarth=[&]{auto *w=open("Earth");auto *p=dynamic_cast<CelestialBodyPanel *>(w->widget());require(p,"Actual Earth panel absent");p->findChild<QTabWidget *>("bodyPages")->setCurrentIndex(2);events();auto *model=p->findChild<QLineEdit *>("body_RotationDataSource");require(model&&model->isReadOnly()&&model->text()=="FK5IAU1980"&&!p->findChild<QPushButton *>("bodyChoose_RotationDataSource"),"Earth FK5 read-only source differs");require(earth()->GetStringParameter("RotationDataSource")=="FK5IAU1980","Earth native source differs");acceptanceView(*w);return p;};
  auto *body=viewEarth();auto *interval=body->findChild<QLineEdit *>("body_NutationUpdateInterval");require(interval&&interval->isEnabled()&&!interval->isReadOnly()&&interval->text().toDouble()==60,"Earth update interval field missing");const auto before=rig.source->toPlainText();interval->setText("0");events();require(body->hasChanges()&&rig.source->toPlainText()==before&&earth()->GetRealParameter("NutationUpdateInterval")==60,"Earth pending interval leaked");body->findChild<QDialogButtonBox *>()->button(QDialogButtonBox::Apply)->click();events();require(earth()->GetRealParameter("NutationUpdateInterval")==0,"Earth interval Apply failed");const auto applied=rig.source->toPlainText();require(applied.endsWith(mission),"Earth edits changed mission");rig.closePanels();rig.source->undo();require(rig.source->toPlainText()==before&&rig.window.buildScript()&&earth()->GetRealParameter("NutationUpdateInterval")==60,"Earth Undo failed");rig.source->redo();require(rig.source->toPlainText()==applied&&rig.window.buildScript()&&earth()->GetRealParameter("NutationUpdateInterval")==0,"Earth Redo failed");
  QJsonArray samples;double maxp=0,maxv=0;for(int phase=0;phase<2;++phase){if(phase){const auto path=rig.files.filePath("Earth FK5 Ω.script");require(rig.window.saveScriptTo(path)&&rig.window.loadScript(path)&&rig.window.buildScript()&&rig.source->toPlainText()==applied,"Earth Unicode save/reopen failed");auto *p=viewEarth();require(p->findChild<QLineEdit *>("body_NutationUpdateInterval")->text().toDouble()==0,"Earth interval lost on reopen");rig.closePanels();}rig.messages->clear();const auto result=rig.window.runMission();events();rig.save(QString::number(phase)+"-messages.txt",rig.messages->toPlainText().toUtf8());if(result!=MainWindow::RunResult::Completed)std::cerr<<rig.messages->toPlainText().toStdString();require(result==MainWindow::RunResult::Completed,"Earth FK5 mission failed");const auto bytes=read(rig.report);rig.save(QString::number(phase)+"-states.csv",bytes);const auto lines=QString::fromUtf8(bytes).trimmed().split('\n');require(lines.size()==rows.size(),"Earth FK5 raw row count differs");
   for(int row=0;row<rows.size();++row){const auto spec=rows[row].toObject();const auto columns=lines[row].split(',');require(columns.size()==14,"Earth FK5 raw field count differs");QJsonArray raw;for(const auto &column:columns){bool ok=false;double value=column.toDouble(&ok);require(ok&&std::isfinite(value),"Earth FK5 nonfinite output");raw.append(value);}require(std::abs(raw[0].toDouble()-spec["tai_mjd"].toDouble())<=matrix["time_tolerance_days"].toDouble()&&std::abs((raw[1].toDouble()-raw[0].toDouble())*86400-32.184)<1e-6,"Earth FK5 independent epoch differs");for(int i=0;i<6;++i){require(std::abs(raw[2+i].toDouble()-spec["input_state"].toArray()[i].toDouble())<1e-8,"Earth FK5 inertial input differs");const double difference=std::abs(raw[8+i].toDouble()-spec["fixed_state"].toArray()[i].toDouble());if(i<3)maxp=std::max(maxp,difference);else maxv=std::max(maxv,difference);const double tolerance=matrix[i<3?"position_tolerance_km":"velocity_tolerance_km_s"].toDouble();if(difference>tolerance)std::cerr<<"EARTH_DIFF row="<<row<<" component="<<i<<" actual="<<raw[8+i].toDouble()<<" expected="<<spec["fixed_state"].toArray()[i].toDouble()<<" error="<<difference<<std::endl;require(difference<=tolerance,"Earth FK5 state differs from independent reference");}samples.append(QJsonObject{{"phase",phase},{"row",row},{"raw",raw}});}
   require(Moderator::Instance()->GetInternalObject("Keep")->GetRealParameter("Value")==42&&rig.source->toPlainText()==applied,"Earth FK5 continuation/source differs");auto *outputs=rig.window.findChild<QTreeWidget *>("Output");auto entries=outputs->findItems("States",Qt::MatchExactly|Qt::MatchRecursive);require(entries.size()==1,"Earth FK5 report entry absent");outputs->itemDoubleClicked(entries.first(),0);events();auto *viewer=rig.area->activeSubWindow();require(viewer&&dynamic_cast<ReportViewer *>(viewer->widget()),"Actual Earth FK5 viewer absent");auto *shown=viewer->findChild<QPlainTextEdit *>();require(shown&&shown->isReadOnly()&&shown->toPlainText().trimmed()==QString::fromUtf8(bytes).trimmed(),"Earth FK5 viewer bytes differ");acceptanceView(*viewer);rig.closePanels();
  }
  rig.save("final.script",applied.toUtf8());const QJsonObject proof{{"checkpoint","earth-fk5-orientation"},{"outcome","passed"},{"model","FK5"},{"phases",2},{"samples",samples},{"max_position_error_km",maxp},{"max_velocity_error_km_s",maxv},{"scope","Earth FK5 orientation only; independent scientific/core and complete dynamics gates remain open."}};rig.save("proof.json",QJsonDocument(proof).toJson());std::cout<<"NASA_CHECK "<<QJsonDocument(proof).toJson(QJsonDocument::Compact).constData()<<std::endl;return 0;
 }catch(BaseException &e){std::cerr<<"FAIL "<<e.GetFullMessage()<<std::endl;}catch(std::exception &e){std::cerr<<"FAIL "<<e.what()<<std::endl;}return 1;
}
